class Program
{
    // сколько раз встретился каждый тег
    public static Dictionary<string, int> TagCounts(List<string> tags)
    {
        var counts = new Dictionary<string, int>();
        foreach (string tag in tags)
        {
            counts[tag] = counts.GetValueOrDefault(tag) + 1;
        }
        return counts;
    }

    static void Main()
