class Program
{
    // цены, которые укладываются в бюджет
    public static List<int> Affordable(List<int> prices, int budget)
    {
        var result = new List<int>();
        foreach (int price in prices)
        {
            if (price <= budget)
            {
                result.Add(price);
            }
        }
        return result;
    }

    static void Main()
    {
        Console.WriteLine(string.Join(", ", Affordable(new List<int> { 500, 1500, 999, 2000 }, 1000)));
    }
}

