class Program
{
    // сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
    public static int DigitSum(long n)
    {
        n = Math.Abs(n);
        if (n < 10)
        {
            return (int)n;
        }
        return (int)(n % 10) + DigitSum(n / 10);
    }

    static void Main()
    {
        Console.WriteLine(DigitSum(1990));
    }
}

